-- challenge chal_coding_otl_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_otl_122', (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-otl-1-2' AND is_deleted = false LIMIT 1), 'structured-json-log-formatter', 'A JSON logger that joins logs to traces', 'When a grading job failed on CodeDev, the worker logged "Grading failed for submission" as plain text: no trace id, no submission id, an expired bearer token printed in full, and an Error that came out as {}. Nobody could join that line to the POST /submissions request that failed. Write createLogger(options, bindings = {}), a small pino-style JSON logger used by the API and the worker. logger.log(level, msg, fields?) writes exactly one line with options.write(line): a JSON object (JSON.stringify, no spaces) whose keys come in this order: time (new Date(options.now()).toISOString()), level (the level name), msg, trace_id and span_id (traceId and spanId of options.activeSpan(), read when the line is written; both keys are left out when it returns null), then the remaining fields sorted by key with the default string sort. The remaining fields are the logger''s bindings merged with the call''s fields, the call''s fields winning; fields named time, level, msg, trace_id or span_id are dropped. Rules for every value at any depth (nested objects and arrays; only the top level is sorted, nested keys keep their order): a key whose value is undefined is dropped before merging (so an undefined call field leaves the binding as it was), an undefined array item becomes null; a key that matches an entry of options.redact, compared case-insensitively, gets the value "[REDACTED]" whatever its value was; an Error becomes {"name","message","stack"} where stack is the first frame of error.stack (the first line that starts with "at " once trimmed), and the stack key is left out when there is no such line; a string longer than options.maxStringLength (string length) becomes its first maxStringLength characters followed by "...[truncated]" - msg and the Error''s name, message and stack included. Levels are trace 10, debug 20, info 30, warn 40, error 50, fatal 60; a record is written when its level is >= options.level and skipped otherwise. An unknown level, in options.level (when createLogger is called) or in a call, throws new Error("unknown level: <level>"). logger.child(bindings) returns a logger whose bindings are the parent''s merged with the new ones (the new ones win, an undefined one is not set), writing through the same options. Input (JSON on stdin): { config: { level, redact, maxStringLength }, steps }. The runner builds options around a fake clock starting at 2026-10-20T09:14:03.000Z and a stack of active spans, replays the steps (advance, enter/exit a span, child, log), and prints every line written, or "!! <message>" when a call throws. In the input, {"$error": {...}} stands for an Error object and {"$undefined": true} for undefined.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
