INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_122'), 1, 'Which parts of a line does the logger own and which come from the caller, and in which order do bindings, call fields and the five fixed keys meet? Then: which rules apply to a value no matter how deep it sits?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_122'), 2, 'Look at three places. Where you call options.activeSpan(): inside log, at write time, not when the logger is created. The spread that merges bindings with call fields: the one written last wins. And one recursive function that every value goes through - strings, Errors (check instanceof Error before the plain-object case: an Error''s message and stack are not enumerable), arrays and plain objects - where object keys are checked for undefined and for redaction before the value is visited.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_122'), 3, 'A similar record on other data: redact ["apiKey"], maxStringLength 10, level info, no active span, bindings { region: "sg" }, logger.log("info", "cfg", { region: "vn", config: { ApiKey: "k_123", note: "a long note here" }, tags: ["a", undefined] }) at 2026-01-02T03:04:05.000Z writes {"time":"2026-01-02T03:04:05.000Z","level":"info","msg":"cfg","config":{"ApiKey":"[REDACTED]","note":"a long not...[truncated]"},"region":"vn","tags":["a",null]}. The same call at level debug writes nothing.');
