-- challenge chal_quiz_otl_131 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_otl_131', (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-otl-1-3' AND is_deleted = false LIMIT 1), 'trace-context-quiz', 'Does this header continue the trace?', 'Headers captured between the CodeDev edge gateway, the API and grading-service on the day one submission showed up as three separate traces.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_131');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_131');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_131'), 'The edge gateway adds the header with a hand-written middleware:

const traceId = randomBytes(16).toString("hex").toUpperCase();
const spanId = randomBytes(8).toString("hex").toUpperCase();
req.headers.traceparent = `00-${traceId}-${spanId}-01`;

Request captured at the API:
traceparent: 00-4BF92F3577B34DA6A3CE929D0E0E4736-00F067AA0BA902B7-01

The trace backend shows the gateway''s span in trace 4bf92f3577b34da6a3ce929d0e0e4736 and the API''s POST /submissions span as the root of another trace, 9c2e41d0a7b35f6e81d4c0b2a9f3e7d5.

Statement: "Removing .toUpperCase() from the middleware lets the API''s span join the gateway''s trace, with no change in the API."', 'single_choice'::question_type, 'True. W3C Trace Context defines trace-id and parent-id as lowercase hex (HEXDIGLC), and a receiver must ignore a traceparent whose ids contain anything else. The API''s propagator did exactly that: it treated the request as having no parent and started a new trace. With lowercase ids the same header is valid, the API continues trace 4bf92f35... and its server span gets 00f067aa0ba902b7 as parent. Note the backend already shows the gateway''s trace id in lowercase: it normalised it for display, which hides the problem in the UI. The misconception is that hex is hex: some parsers accept both cases, the spec does not, and a header that one hop accepts can be dropped by the next.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_131') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_131'), 'After the gateway fix, the API receives:
traceparent: 00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01

The API''s server span for POST /submissions has span id 53995c3f42cd8ad8, and the HTTP client span for its call to grading-service has span id e457b5a2e4d86bd1. A reviewer proposes this for the outgoing call:

headers.traceparent = req.headers.traceparent; // forward as received

Statement: "Forwarding the header as received is correct: grading-service then sees parent-id 00f067aa0ba902b7 and its span appears under the API''s call in the trace view."', 'single_choice'::question_type, 'False. parent-id is the id of the caller''s span, and each hop replaces it. The header the API sends must be 00-4bf92f3577b34da6a3ce929d0e0e4736-e457b5a2e4d86bd1-01: same trace-id, the API''s client span as parent, sampled flag kept. Forwarding the gateway''s header keeps the trace id, so the spans are still in one trace, but grading-service''s span becomes a child of the gateway span 00f067aa0ba902b7, a sibling of the API''s span: the tree no longer shows that grading ran inside the API''s call, and the API''s client span has no child. The misconception is that keeping the trace id is enough; the parent-id is what builds the tree, and an OpenTelemetry propagator writes it from the active span when you inject into the outgoing headers.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
