        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_otl_132 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_otl_132', (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-otl-1-3' AND is_deleted = false LIMIT 1), 'w3c-traceparent-propagation', 'Parse traceparent and continue the trace', 'The edge gateway in front of the CodeDev API wrote traceparent headers with upper-case ids, the API''s tracer rejected them and started new traces, and the API then forwarded the header it had received to grading-service unchanged, so the trace view showed three disconnected pieces of one submission. Write the propagation code of the API''s outgoing call to grading-service, following W3C Trace Context (https://www.w3.org/TR/trace-context/). parseTraceparent(header) returns { version, traceId, parentId, sampled } or null when the header is null or invalid. Trim spaces and tabs at both ends first. The header must be at least 55 characters; version is characters 0-1, two lowercase hex digits followed by "-", and "ff" is invalid. Version "00" must be exactly 55 characters: 00-<trace-id>-<parent-id>-<trace-flags>. A higher version (01 to fe) is parsed from its first 55 characters the same way, and when it is longer, character 55 must be "-" (the rest is not read). trace-id is 32, parent-id 16 and trace-flags 2 characters of lowercase hex (0-9, a-f only) with "-" between them; a trace-id or parent-id made only of zeros is invalid; sampled is the lowest bit of trace-flags (flags & 0x01). validTracestate(header) is true when the header is at most 512 characters and, split on "," with spaces and tabs trimmed around each member, has at least 1 and at most 32 non-empty members (empty members are allowed and ignored), no key twice, each member being key=value split at the first "=": key matches [a-z][a-z0-9_\-*/]{0,255} or [a-z0-9][a-z0-9_\-*/]{0,240}@[a-z][a-z0-9_\-*/]{0,13}, value is 1 to 256 characters from 0x20-0x7E except "," and "=" and does not end with a space. childHeaders(incoming, ids) returns { traceparent, tracestate } for the outgoing call. With a valid parent: "00-<same trace-id>-<new span id>-<flags>", where flags is "01" when sampled and "00" otherwise (always version 00, other flag bits set to 0), and tracestate is the exact string received when it is not null and valid, otherwise null. With a missing or invalid parent: a new trace, "00-<new trace id>-<new span id>-01", and tracestate null (never parse tracestate without a valid traceparent). New ids come from ids.traceId() (32 hex) and ids.spanId() (16 hex); an id made only of zeros must not be sent: draw again. Input (JSON on stdin): { traceIds, spanIds, requests: [{ traceparent?, tracestate? }] }; the id source returns the listed ids in turn. Output: a JSON array with, per request, { parent: parseTraceparent(traceparent), traceparent, tracestate } from childHeaders.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_132');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_132'), 1, 'A traceparent has fixed positions: where must the three dashes be for version 00, and what changes for a version you do not know yet? And of the four parts, which one does a service replace before it calls the next service?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_132'), 2, 'Look at the order of your checks in parseTraceparent: trim, length, version (hex, not ff, then exact length for 00 or the character at index 55 for higher versions), then each field with a lowercase-only hex test (no i flag) and the all-zero test. In childHeaders the trace id stays, the span id is always new, and the flags are rebuilt from the sampled bit, not copied. tracestate is only looked at after the parent is valid.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_132'), 3, 'Worked on other values: "00-11112222333344445555666677778888-aaaabbbbccccdddd-05" is valid (version 00, 55 characters) and 0x05 has the lowest bit set, so it is sampled; with a span id source returning "0000000000000000" then "1234567890abcdef", the outgoing header is "00-11112222333344445555666677778888-1234567890abcdef-01". "0a-11112222333344445555666677778888-aaaabbbbccccdddd-04+x" is invalid because character 55 is "+", while the same header ending in "-04-x" is accepted with sampled false. A tracestate of "acme=1,ACME=2" is dropped (upper-case key).');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_132'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
