VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_132'), 'Valid parents keep trace id and sampled flag; a missing header starts a new trace', '{"traceIds":["a3ce929d0e0e47364bf92f3577b34da6","5b8efff798038103d269b633813fc60c"],"spanIds":["53995c3f42cd8ad8","e457b5a2e4d86bd1","cddd5e3d6c8f1a20","1f2e3d4c5b6a7980"],"requests":[{"traceparent":"00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01","tracestate":"codedev=s_981,rojo=00f067aa0ba902b7"},{"traceparent":"00-0af7651916cd43dd8448eb211c80319c-b7ad6b7169203331-00"},{},{"traceparent":"","tracestate":"codedev=s_982"}]}', '[{"parent":{"version":"00","traceId":"4bf92f3577b34da6a3ce929d0e0e4736","parentId":"00f067aa0ba902b7","sampled":true},"traceparent":"00-4bf92f3577b34da6a3ce929d0e0e4736-53995c3f42cd8ad8-01","tracestate":"codedev=s_981,rojo=00f067aa0ba902b7"},{"parent":{"version":"00","traceId":"0af7651916cd43dd8448eb211c80319c","parentId":"b7ad6b7169203331","sampled":false},"traceparent":"00-0af7651916cd43dd8448eb211c80319c-e457b5a2e4d86bd1-00","tracestate":null},{"parent":null,"traceparent":"00-a3ce929d0e0e47364bf92f3577b34da6-cddd5e3d6c8f1a20-01","tracestate":null},{"parent":null,"traceparent":"00-5b8efff798038103d269b633813fc60c-1f2e3d4c5b6a7980-01","tracestate":null}]', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_132'), 'The incident: upper-case ids, all-zero ids and version ff are rejected', '{"traceIds":["a3ce929d0e0e47364bf92f3577b34da6","5b8efff798038103d269b633813fc60c"],"spanIds":["53995c3f42cd8ad8","e457b5a2e4d86bd1","cddd5e3d6c8f1a20","1f2e3d4c5b6a7980"],"requests":[{"traceparent":"00-4BF92F3577B34DA6A3CE929D0E0E4736-00F067AA0BA902B7-01","tracestate":"codedev=s_981"},{"traceparent":"00-00000000000000000000000000000000-00f067aa0ba902b7-01"},{"traceparent":"00-4bf92f3577b34da6a3ce929d0e0e4736-0000000000000000-01"},{"traceparent":"ff-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01"},{"traceparent":"00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01","tracestate":"codedev=s_981"}]}', '[{"parent":null,"traceparent":"00-a3ce929d0e0e47364bf92f3577b34da6-53995c3f42cd8ad8-01","tracestate":null},{"parent":null,"traceparent":"00-5b8efff798038103d269b633813fc60c-e457b5a2e4d86bd1-01","tracestate":null},{"parent":null,"traceparent":"00-a3ce929d0e0e47364bf92f3577b34da6-cddd5e3d6c8f1a20-01","tracestate":null},{"parent":null,"traceparent":"00-5b8efff798038103d269b633813fc60c-1f2e3d4c5b6a7980-01","tracestate":null},{"parent":{"version":"00","traceId":"4bf92f3577b34da6a3ce929d0e0e4736","parentId":"00f067aa0ba902b7","sampled":true},"traceparent":"00-4bf92f3577b34da6a3ce929d0e0e4736-53995c3f42cd8ad8-01","tracestate":"codedev=s_981"}]', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_132'), 'Higher versions: parse the first 55 characters and answer with version 00', '{"traceIds":["a3ce929d0e0e47364bf92f3577b34da6","5b8efff798038103d269b633813fc60c"],"spanIds":["53995c3f42cd8ad8","e457b5a2e4d86bd1","cddd5e3d6c8f1a20","1f2e3d4c5b6a7980"],"requests":[{"traceparent":"01-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01-what-the-future-holds","tracestate":"vendor=1"},{"traceparent":"cc-0af7651916cd43dd8448eb211c80319c-b7ad6b7169203331-00"},{"traceparent":"02-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01x"},{"traceparent":"01-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-0"},{"traceparent":"fe-0af7651916cd43dd8448eb211c80319c-00f067aa0ba902b7-03-ab"},{"traceparent":"0g-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01"},{"traceparent":"1-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01-x"},{"traceparent":"01-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01-"}]}', '[{"parent":{"version":"01","traceId":"4bf92f3577b34da6a3ce929d0e0e4736","parentId":"00f067aa0ba902b7","sampled":true},"traceparent":"00-4bf92f3577b34da6a3ce929d0e0e4736-53995c3f42cd8ad8-01","tracestate":"vendor=1"},{"parent":{"version":"cc","traceId":"0af7651916cd43dd8448eb211c80319c","parentId":"b7ad6b7169203331","sampled":false},"traceparent":"00-0af7651916cd43dd8448eb211c80319c-e457b5a2e4d86bd1-00","tracestate":null},{"parent":null,"traceparent":"00-a3ce929d0e0e47364bf92f3577b34da6-cddd5e3d6c8f1a20-01","tracestate":null},{"parent":null,"traceparent":"00-5b8efff798038103d269b633813fc60c-1f2e3d4c5b6a7980-01","tracestate":null},{"parent":{"version":"fe","traceId":"0af7651916cd43dd8448eb211c80319c","parentId":"00f067aa0ba902b7","sampled":true},"traceparent":"00-0af7651916cd43dd8448eb211c80319c-53995c3f42cd8ad8-01","tracestate":null},{"parent":null,"traceparent":"00-a3ce929d0e0e47364bf92f3577b34da6-e457b5a2e4d86bd1-01","tracestate":null},{"parent":null,"traceparent":"00-5b8efff798038103d269b633813fc60c-cddd5e3d6c8f1a20-01","tracestate":null},{"parent":{"version":"01","traceId":"4bf92f3577b34da6a3ce929d0e0e4736","parentId":"00f067aa0ba902b7","sampled":true},"traceparent":"00-4bf92f3577b34da6a3ce929d0e0e4736-1f2e3d4c5b6a7980-01","tracestate":null}]', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_132'), 'Version 00 is exactly 55 characters; spaces and tabs around it are trimmed', '{"traceIds":["a3ce929d0e0e47364bf92f3577b34da6","5b8efff798038103d269b633813fc60c"],"spanIds":["53995c3f42cd8ad8","e457b5a2e4d86bd1","cddd5e3d6c8f1a20","1f2e3d4c5b6a7980"],"requests":[{"traceparent":"00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01-extra"},{"traceparent":"00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-1"},{"traceparent":" \t00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01\t ","tracestate":"rojo=1"},{"traceparent":"00_4bf92f3577b34da6a3ce929d0e0e4736_00f067aa0ba902b7_01"},{"traceparent":"00-4bf92f3577b34da6a3ce929d0e0e473-a00f067aa0ba902b7-01"},{"traceparent":"00-4bf92f3577b34da6a3ce929d0e0e4736 -00f067aa0ba902b7-01"},{"traceparent":"00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902bz-01"}]}', '[{"parent":null,"traceparent":"00-a3ce929d0e0e47364bf92f3577b34da6-53995c3f42cd8ad8-01","tracestate":null},{"parent":null,"traceparent":"00-5b8efff798038103d269b633813fc60c-e457b5a2e4d86bd1-01","tracestate":null},{"parent":{"version":"00","traceId":"4bf92f3577b34da6a3ce929d0e0e4736","parentId":"00f067aa0ba902b7","sampled":true},"traceparent":"00-4bf92f3577b34da6a3ce929d0e0e4736-cddd5e3d6c8f1a20-01","tracestate":"rojo=1"},{"parent":null,"traceparent":"00-a3ce929d0e0e47364bf92f3577b34da6-1f2e3d4c5b6a7980-01","tracestate":null},{"parent":null,"traceparent":"00-5b8efff798038103d269b633813fc60c-53995c3f42cd8ad8-01","tracestate":null},{"parent":null,"traceparent":"00-a3ce929d0e0e47364bf92f3577b34da6-e457b5a2e4d86bd1-01","tracestate":null},{"parent":null,"traceparent":"00-5b8efff798038103d269b633813fc60c-cddd5e3d6c8f1a20-01","tracestate":null}]', 3, false, true, 4),
