-- challenge chal_coding_otl_212 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_otl_212', (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-otl-2-1' AND is_deleted = false LIMIT 1), 'keep-trace-context-across-async', 'Keep the trace context across callbacks and the queue', 'Since grading moved to a queue worker, the callbacks of POST /submissions on CodeDev log without a trace id (or with the trace of the antivirus poller) and the worker''s "process grading" span starts a new trace. The file contains a tiny tracer and a context store: store.run(ctx, fn) makes ctx active only while fn runs synchronously, store.active() returns it (undefined when none). The store has no async tracking, so every callback that runs later sees no context, or the context of whoever calls it, unless you carry the context to it. The app code already calls your three helpers; write them:

- bind(fn): capture the context that is active when bind is called and return a function that runs fn with that context active (passing the arguments through and returning fn''s result).
- inject(headers): when a context is active, set headers.traceparent to "00-<traceId>-<spanId>-01"; when none is active, leave headers unchanged.
- extract(headers): read headers.traceparent and return { traceId, spanId }, or null when the header is missing or invalid. Valid means: version "00", a 32-character and a 16-character id of lowercase hex digits, 2 hex digits of flags, separated by "-", and neither id all zeros. Any other version is invalid in this challenge.

Input (stdin): { "requests": [{ "id": "sub_101", "traceparent"?: string, "timerMs": number, "jobHeader"?: string | null }] }. The runner handles the requests one after another, then lets promises settle, fires the timers in time order, lets the antivirus poller report the scans (newest first, from its own span), and runs the worker on each job in queue order (jobHeader replaces the job''s traceparent on its way through the queue; null removes it).
Output: one line per span start (span "name" trace=... span=... parent=...|none) and per log line (<id> <step>: trace=... span=... or: no context). Ids are deterministic. Do not change the store, the tracer, the app code or the test runner.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
