INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_212'), 1, 'A callback can only see the context that was active at some moment you saved. Which moment do you need: when bind() is called inside the request, or when the scheduler, the emitter or the promise finally calls the callback?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_212'), 2, 'Look at what bind() returns and where the captured value lives. Each call to bind() needs its own captured context; with three requests in flight, a single shared variable is overwritten by the last one. For extract(), list every way a traceparent can be wrong before writing the check.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_212'), 3, 'A similar case on other data: function withUser(fn) { const user = session.current(); return (...args) => session.as(user, () => fn(...args)); } saves the user when withUser runs and restores it when the returned function runs, however much later. For parsing, a header like "v1;id=abc" is safer checked with one anchored regular expression than with split(";"), which accepts too much.');
