-- challenge chal_quiz_otl_231 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_otl_231', (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-otl-2-3' AND is_deleted = false LIMIT 1), 'span-design-review', 'Review the span design', 'Three statements from CodeDev''s first tracing review: span names built from raw paths, a span carrying a token and a password hash, and a grading timeout that left no trace under head sampling. Decide which design rule each piece of evidence breaks and what the fix does.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
