UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_231');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_231'), 'Span names of submissions-api, last 7 days (2,184,331 distinct names):
GET /courses/8812/lessons/3      count 41
GET /courses/8812/lessons/4      count 38
GET /courses/9921/lessons/1      count 12
...

Proposed change: name the server span from the route template and move the ids to attributes:
span name   GET /courses/:courseId/lessons/:lessonId
attributes  http.route = "/courses/:courseId/lessons/:lessonId", course.id = "8812", lesson.id = "3"

Statement: "After the change the span name has one value for this route however many courses and lessons exist, and support can still find every request for course 8812 by searching course.id = 8812."', 'single_choice'::question_type, 'True. The route template is the same for every course and lesson, so the operation list shrinks to roughly one name per route, and latency breakdowns per operation become meaningful again. The ids are not lost: trace backends index span attributes and are built to search high-cardinality values, which is how a single submission or course is found. The common misconception is that low-cardinality names mean losing the ability to find a specific request; the detail moves to attributes, it does not disappear. (Ids as metric labels are a different matter, covered in module 3.)', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_231') AND order_index = 1)
    RETURNING id
)
