WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_311'), 'Grafana panel "Submit latency p95". Each API instance computes its own p95 in process (a summary) and exports it as submit_latency_p95_seconds. The panel query is:

avg(submit_latency_p95_seconds)

Last 30 minutes, per instance:
instance  requests  p95
api-1     4200      0.21 s
api-2     4100      0.20 s
api-3     700       3.80 s
panel     -         1.40 s

Statement: "1.40 s is the p95 of all 9,000 submit requests of these 30 minutes."', 'single_choice'::question_type, 'False. The average of three percentiles is not a percentile of anything. It gives api-3, which served 700 requests, the same weight as api-1 with 4,200, and three numbers cannot tell you how many of the 9,000 requests were slower than any given time. The p95 of all requests is the time under which 8,550 of them finished; to compute it you need the counts per latency range from every instance, summed: export a histogram, sum its buckets by le across instances and apply histogram_quantile to the sum. The misconception is that percentiles can be combined like counts or sums; they cannot be averaged, added or merged.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_311') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_311'), 'PromQL, last 5 minutes of POST /submissions on all instances:

sum by (le) (increase(http_server_request_duration_seconds_bucket{http_route="/submissions"}[5m]))
le="0.1"   610
le="0.25"  900
le="0.5"   960
le="1"     990
le="+Inf"  1000

histogram_quantile(0.95, sum by (le) (rate(http_server_request_duration_seconds_bucket{http_route="/submissions"}[5m])))
=> 0.4583

Statement: "The real p95 of these requests lies between 0.25 s and 0.5 s; the value 0.458 s comes from assuming that the 60 requests of that bucket are spread evenly across it."', 'single_choice'::question_type, 'True. The 950th of 1,000 requests is in the bucket from 0.25 s to 0.5 s: 900 requests finished within 0.25 s and 960 within 0.5 s. That is all the buckets know. histogram_quantile places the rank linearly inside the bucket: 0.25 + 0.25 x (950 - 900) / 60 = 0.458 s. If those 60 requests were all close to 0.26 s the real p95 would be about 0.26 s; if they were all close to 0.49 s, about 0.49 s. The error is bounded by the width of the bucket, which is why you put bucket boundaries near the thresholds you care about, such as an SLO at 0.5 s. The misconception is to read 0.458 as a measured value with three digits of precision.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_311') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_otl_312 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_otl_312', (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-otl-3-1' AND is_deleted = false LIMIT 1), 'percentiles-from-histogram-buckets', 'Percentiles from histogram buckets', 'The CodeDev latency dashboard for POST /submissions must show p50, p95 and p99 over all API instances, like this PromQL query: histogram_quantile(q, sum by (le) (increase(http_server_request_duration_seconds_bucket[window]))). There is no Prometheus in the code runner: you get, for each instance, two snapshots of its cumulative buckets (start and end of the window) and compute the same numbers yourself. Write three functions.

counterIncrease(start, end): how much a counter grew between two snapshots. Counters only go up, so an end value lower than the start value means the process restarted and the counter began again at 0: the increase is then the end value. Otherwise it is end - start.

mergeIncreases(instances): for every instance and every bucket of its end snapshot, the increase of that bucket (counterIncrease of the start and end counts with the same le; a bucket missing from start - the instance started during the window - counts from 0). Add the increases of all instances bucket by bucket (same le): sum the buckets, never average the percentiles of each instance. Return one { le, count } per le, sorted by le ascending (+Inf, given as Infinity, last).

histogramQuantile(q, buckets), on cumulative buckets sorted by le, exactly like Prometheus: (1) q < 0 returns -Infinity and q > 1 returns Infinity; (2) no +Inf bucket, or fewer than 2 buckets, returns NaN; total = count of the +Inf bucket, and total 0 returns NaN; (3) rank = q * total; find the first bucket other than +Inf whose count >= rank; (4) if there is none (the rank falls in the +Inf bucket), return the le of the highest bucket other than +Inf; (5) otherwise interpolate linearly inside that bucket: lower = le of the previous bucket (0 for the first bucket), before = count of the previous bucket (0 for the first), result = lower + (le - lower) * (rank - before) / (count - before).

Input (stdin, JSON): { "windowSeconds": 300, "quantiles": [0.5, 0.95, 0.99], "instances": [{ "instance": "api-1", "start": [{ "le": "0.1", "count": 180 }, ..., { "le": "+Inf", "count": 400 }], "end": [...] }] }. The runner turns le into a number (Infinity for "+Inf") and prints the request count of the window (the +Inf bucket of your merged buckets, 0 without one), its rate per second with 3 decimals, then one line per quantile in milliseconds, rounded to the nearest millisecond, for example "p95 609 ms" (NaN, +Inf and -Inf are printed as such). Boundaries are positive and the same on every instance; buckets are cumulative.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_312');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_312'), 1, 'A bucket le="0.5" counts every request that took 0.5 s or less since the process started. What do you have to do to its two snapshots to know how many requests of the window took 0.5 s or less, on one instance and then on all of them?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_312'), 2, 'Look at three places: the restart rule in counterIncrease (an end value lower than its start), the +Inf bucket (it gives the total, but it is never the bucket you interpolate in), and the lower edge of the first bucket, which is 0. Check the special cases (q outside 0..1, no +Inf bucket, total 0) before you compute the rank.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_312'), 3, 'A worked example on other numbers: cumulative buckets le 0.2 -> 40, le 0.4 -> 70, le 0.8 -> 95, +Inf -> 100. For q = 0.6 the rank is 60: the first bucket with count >= 60 is le 0.4, so lower 0.2, before 40 and the result is 0.2 + 0.2 x (60 - 40) / (70 - 40) = 0.333 s. For q = 0.97 the rank is 97, which no finite bucket reaches, so the result is 0.8. An instance whose le 0.2 bucket went from 500 to 12 restarted: its increase is 12.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_312'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
