32},{"le":"0.1","count":62},{"le":"0.25","count":152},{"le":"0.5","count":232},{"le":"0.75","count":292},{"le":"1","count":362},{"le":"2.5","count":482},{"le":"5","count":542},{"le":"7.5","count":554},{"le":"10","count":557},{"le":"+Inf","count":557}],"end":[{"le":"0.005","count":0},{"le":"0.01","count":0},{"le":"0.025","count":3},{"le":"0.05","count":16},{"le":"0.075","count":42},{"le":"0.1","count":82},{"le":"0.25","count":202},{"le":"0.5","count":310},{"le":"0.75","count":392},{"le":"1","count":487},{"le":"2.5","count":657},{"le":"5","count":743},{"le":"7.5","count":761},{"le":"10","count":766},{"le":"+Inf","count":766}]}]}', '"requests 2170 in 300 s = 7.233/s\np50 94 ms\np95 928 ms\np99 3777 ms"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_312'), 'An instance restarted during the window: its counters began again at 0', '{"windowSeconds":300,"quantiles":[0.5,0.95,0.99],"instances":[{"instance":"api-1","start":[{"le":"0.005","count":5},{"le":"0.01","count":35},{"le":"0.025","count":155},{"le":"0.05","count":555},{"le":"0.075","count":1055},{"le":"0.1","count":1505},{"le":"0.25","count":2205},{"le":"0.5","count":2505},{"le":"0.75","count":2595},{"le":"1","count":2635},{"le":"2.5","count":2655},{"le":"5","count":2659},{"le":"7.5","count":2659},{"le":"10","count":2659},{"le":"+Inf","count":2659}],"end":[{"le":"0.005","count":6},{"le":"0.01","count":44},{"le":"0.025","count":214},{"le":"0.05","count":774},{"le":"0.075","count":1464},{"le":"0.1","count":2084},{"le":"0.25","count":3044},{"le":"0.5","count":3444},{"le":"0.75","count":3559},{"le":"1","count":3609},{"le":"2.5","count":3634},{"le":"5","count":3639},{"le":"7.5","count":3639},{"le":"10","count":3639},{"le":"+Inf","count":3639}]},{"instance":"api-2","start":[{"le":"0.005","count":40},{"le":"0.01","count":340},{"le":"0.025","count":1540},{"le":"0.05","count":5640},{"le":"0.075","count":10840},{"le":"0.1","count":15140},{"le":"0.25","count":22040},{"le":"0.5","count":25140},{"le":"0.75","count":25940},{"le":"1","count":26390},{"le":"2.5","count":26570},{"le":"5","count":26600},{"le":"7.5","count":26602},{"le":"10","count":26602},{"le":"+Inf","count":26602}],"end":[{"le":"0.005","count":0},{"le":"0.01","count":2},{"le":"0.025","count":12},{"le":"0.05","count":52},{"le":"0.075","count":112},{"le":"0.1","count":182},{"le":"0.25","count":322},{"le":"0.5","count":442},{"le":"0.75","count":532},{"le":"1","count":612},{"le":"2.5","count":672},{"le":"5","count":697},{"le":"7.5","count":701},{"le":"10","count":702},{"le":"+Inf","count":702}]}]}', '"requests 1682 in 300 s = 5.607/s\np50 130 ms\np95 1275 ms\np99 3863 ms"', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_312'), 'p99 falls in the +Inf bucket: the highest finite bound is returned', '{"windowSeconds":60,"quantiles":[0.5,0.9,0.95,0.99],"instances":[{"instance":"api-1","start":[{"le":"0.005","count":0},{"le":"0.01","count":0},{"le":"0.025","count":5},{"le":"0.05","count":25},{"le":"0.075","count":55},{"le":"0.1","count":95},{"le":"0.25","count":185},{"le":"0.5","count":245},{"le":"0.75","count":275},{"le":"1","count":295},{"le":"2.5","count":325},{"le":"5","count":340},{"le":"7.5","count":346},{"le":"10","count":350},{"le":"+Inf","count":360}],"end":[{"le":"0.005","count":0},{"le":"0.01","count":0},{"le":"0.025","count":6},{"le":"0.05","count":32},{"le":"0.075","count":72},{"le":"0.1","count":124},{"le":"0.25","count":244},{"le":"0.5","count":324},{"le":"0.75","count":364},{"le":"1","count":390},{"le":"2.5","count":430},{"le":"5","count":450},{"le":"7.5","count":459},{"le":"10","count":465},{"le":"+Inf","count":480}]},{"instance":"api-2","start":[{"le":"0.005","count":0},{"le":"0.01","count":0},{"le":"0.025","count":4},{"le":"0.05","count":22},{"le":"0.075","count":50},{"le":"0.1","count":88},{"le":"0.25","count":176},{"le":"0.5","count":238},{"le":"0.75","count":266},{"le":"1","count":288},{"le":"2.5","count":316},{"le":"5","count":330},{"le":"7.5","count":337},{"le":"10","count":342},{"le":"+Inf","count":354}],"end":[{"le":"0.005","count":0},{"le":"0.01","count":0},{"le":"0.025","count":6},{"le":"0.05","count":29},{"le":"0.075","count":66},{"le":"0.1","count":115},{"le":"0.25","count":231},{"le":"0.5","count":315},{"le":"0.75","count":352},{"le":"1","count":381},{"le":"2.5","count":418},{"le":"5","count":438},{"le":"7.5","count":447},{"le":"10","count":453},{"le":"+Inf","count":469}]}]}', '"requests 235 in 60 s = 3.917/s\np50 271 ms\np90 3523 ms\np95 7708 ms\np99 10000 ms"', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_312'), 'A new instance started during the window (no start snapshot)', '{"windowSeconds":120,"quantiles":[0.5,0.75,0.99],"instances":[{"instance":"api-1","start":[{"le":"0.005","count":2},{"le":"0.01","count":12},{"le":"0.025","count":72},{"le":"0.05","count":272},{"le":"0.075","count":522},{"le":"0.1","count":752},{"le":"0.25","count":1102},{"le":"0.5","count":1252},{"le":"0.75","count":1297},{"le":"1","count":1317},{"le":"2.5","count":1327},{"le":"5","count":1329},{"le":"7.5","count":1329},{"le":"10","count":1329},{"le":"+Inf","count":1329}],"end":[{"le":"0.005","count":2},{"le":"0.01","count":15},{"le":"0.025","count":95},{"le":"0.05","count":365},{"le":"0.075","count":695},{"le":"0.1","count":1000},{"le":"0.25","count":1470},{"le":"0.5","count":1670},{"le":"0.75","count":1730},{"le":"1","count":1756},{"le":"2.5","count":1769},{"le":"5","count":1772},{"le":"7.5","count":1772},{"le":"10","count":1772},{"le":"+Inf","count":1772}]},{"instance":"api-4","start":[],"end":[{"le":"0.005","count":0},{"le":"0.01","count":0},{"le":"0.025","count":0},{"le":"0.05","count":2},{"le":"0.075","count":6},{"le":"0.1","count":12},{"le":"0.25","count":32},{"le":"0.5","count":62},{"le":"0.75","count":87},{"le":"1","count":109},{"le":"2.5","count":127},{"le":"5","count":135},{"le":"7.5","count":137},{"le":"10","count":137},{"le":"+Inf","count":137}]}]}', '"requests 580 in 120 s = 4.833/s\np50 132 ms\np75 359 ms\np99 3944 ms"', 3, false, true, 5),
