-- challenge chal_quiz_otl_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_otl_321', (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-otl-3-2' AND is_deleted = false LIMIT 1), 'metric-cardinality-quiz', 'How many series will this label create?', 'Two pieces of evidence from the metrics backend: the label counts of the request counter before a proposed change, and the /metrics output after a release that labelled requests with the raw path.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_321');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_321');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_321'), 'PromQL on the request counter today:

count(http_server_requests_total)                                   => 820
count(count by (route) (http_server_requests_total))                => 41
count(count by (method) (http_server_requests_total))               => 5
count(count by (status_class) (http_server_requests_total))         => 4

A pull request adds one label so marketing can see traffic per course:

requests.add(1, { route, method, status_class, course_slug });   // 300 published courses today

Statement: "In the worst case this counter goes from 820 series to about 246,000, because every existing combination can now be split by each of the 300 course slugs."', 'single_choice'::question_type, 'True. A series is one unique combination of label values, so the series count of a metric is bounded by the product of the number of values of each label. Each of the 820 combinations that exist today can appear with each of the 300 slugs: 820 x 300 = 246,000 in the worst case. The real number is usually lower, because course_slug only shows up on course routes, but the bound grows with every published course and the backend pays for each combination that does occur. The misconception is that adding one label adds its number of values (+300); it multiplies.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_321') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_321'), '/metrics on one API instance after a release that labels requests with the raw path:

http_server_requests_total{path="/courses/42/lessons/7",method="GET",status="200"} 1
http_server_requests_total{path="/courses/42/lessons/8",method="GET",status="200"} 2
http_server_requests_total{path="/reset/3f2b8c1e-9a4d-4e7b-8c21-0d5e6f7a8b9c",method="POST",status="204"} 1
http_server_requests_total{path="/courses/react-hooks?utm_source=newsletter",method="GET",status="200"} 1
... (38,000 more lines)

Prometheus: prometheus_tsdb_head_series 1.2M (140k before the release)
Requests per day: 2.1M before and after the release

Statement: "Traffic did not grow and most of these series have a count of 1 or 2, so they add almost nothing to the memory and the bill of the metrics backend."', 'single_choice'::question_type, 'False. The cost of a metrics backend follows the number of active series, not the number of requests: each series has its own index entry, its own chunks in memory and its own samples on every scrape, whether its value is 1 or 1,000,000, and many hosted backends bill per active series. Head series went from 140k to 1.2M with the same traffic, which is exactly the problem. Queries also get slower, because sum by (route) now has to read hundreds of thousands of series. The misconception is to think a counter that rarely increments is cheap; a series costs about the same from the moment it exists.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_321') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_otl_322 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_otl_322', (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-otl-3-2' AND is_deleted = false LIMIT 1), 'metric-cardinality-guard', 'A cardinality guard for metric labels', 'After a release labelled the request counter with raw paths, the CodeDev metrics backend went from 140k to 1.2M active series. Write the guard every metric point now goes through before it is exported: recordAll(points, maxValuesPerLabel) returns the output lines, with the helpers routeTemplate(path) and statusClass(status).

For each point, in input order:
1. Reject it (count it, record nothing) when metric is not a non-empty string or value is not a finite number >= 0.
2. Normalise its labels (a missing labels object means no labels): drop the forbidden labels user_id, email and session_id and every label whose value is ""; replace path with route = routeTemplate(path), except when the point already has a non-empty route label, which is kept (path is then dropped); status keeps its name and becomes statusClass(status); every other label is kept as is.
3. Cap: for each metric and each label name separately, the first maxValuesPerLabel distinct values (after step 2, in the order the points arrive) are kept. A value already kept stays; a new value when that many are already kept becomes "other", and that label name is reported as capped for that metric.
4. Add value to its series: the metric plus all its labels after steps 2 and 3.

routeTemplate(path): cut at the first ? or #, split on /, drop empty segments, replace a segment made only of digits with :id and a UUID (8-4-4-4-12 hexadecimal digits, any case) with :uuid, keep other segments, join with a leading / ("/" when nothing is left). "/courses/42/lessons/7/?tab=hints" -> "/courses/:id/lessons/:id". statusClass(status): a three-digit code from 100 to 599 -> first digit + "xx" ("404" -> "4xx"), anything else -> "unknown".

Input (stdin, JSON): { "maxValuesPerLabel": 3, "points": [{ "metric": "http_server_requests_total", "value": 1, "labels": { "path": "/courses/42", "method": "GET", "status": "200", "user_id": "u_17" } }] }. Output lines: one per series in Prometheus text format, metric{name="value",...} total, label names sorted (just "metric total" without labels), lines sorted by the text before the total in plain string order; then per metric in sorted order "# <metric>: <n> series, capped: <capped label names sorted, joined with ", ">" (or "capped: none"); last "# total: <n> series, <r> rejected".', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
