INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_322'), 1, 'Which of these labels can take a new value every time a new learner, a new course or a new link shows up, and which can only take a handful of values whatever happens? The guard has to turn the first kind into the second, and the cap is the safety net for what the rules did not foresee.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_322'), 2, 'Keep three things apart: normalising a point''s labels (forbidden labels, empty values, path to route, status to class), the cap (it works on normalised values and needs its own memory per metric and per label name, filled in arrival order) and the output (series text with sorted label names, then the sorted lines and the summary). Check whether your cap runs before or after the route template: the order changes which values are kept.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_322'), 3, 'A worked example with other data, maxValuesPerLabel 2 and a label region: the points arrive with region eu, us, eu, ap, sa, us. eu and us are kept, so they stay eu and us every time; ap and sa arrive when two values are already kept and both become other. The metric then has three series for region (eu, us, other) and reports region as capped. A second metric with its own region label starts with an empty list.');
