VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_322'), 'Ids and UUIDs become route templates, statuses become classes, user labels are dropped', '{"maxValuesPerLabel":10,"points":[{"metric":"http_server_requests_total","value":1,"labels":{"path":"/api/courses/42","method":"GET","status":"200","user_id":"u_17"}},{"metric":"http_server_requests_total","value":1,"labels":{"path":"/api/courses/43","method":"GET","status":"200","user_id":"u_18","email":"an@codedev.test"}},{"metric":"http_server_requests_total","value":1,"labels":{"path":"/api/courses/43/lessons/7","method":"GET","status":"200","user_id":"u_18"}},{"metric":"http_server_requests_total","value":1,"labels":{"path":"/api/courses/44/lessons/12","method":"GET","status":"304","session_id":"s_9f1c"}},{"metric":"http_server_requests_total","value":1,"labels":{"path":"/api/challenges/c_17/submissions","method":"POST","status":"201","user_id":"u_17"}},{"metric":"http_server_requests_total","value":1,"labels":{"path":"/api/challenges/c_17/submissions","method":"POST","status":"422","user_id":"u_17"}},{"metric":"http_server_requests_total","value":1,"labels":{"path":"/api/password-reset/3f2b8c1e-9a4d-4e7b-8c21-0d5e6f7a8b9c","method":"POST","status":"204","email":"binh@codedev.test"}},{"metric":"http_server_requests_total","value":1,"labels":{"path":"/api/password-reset/a1b2c3d4-e5f6-4a7b-8c9d-0e1f2a3b4c5d","method":"POST","status":"204","email":"chi@codedev.test"}},{"metric":"http_server_requests_total","value":1,"labels":{"path":"/api/courses/45","method":"GET","status":"404","user_id":"u_30"}}]}', '"http_server_requests_total{method=\"GET\",route=\"/api/courses/:id\",status=\"2xx\"} 2\nhttp_server_requests_total{method=\"GET\",route=\"/api/courses/:id\",status=\"4xx\"} 1\nhttp_server_requests_total{method=\"GET\",route=\"/api/courses/:id/lessons/:id\",status=\"2xx\"} 1\nhttp_server_requests_total{method=\"GET\",route=\"/api/courses/:id/lessons/:id\",status=\"3xx\"} 1\nhttp_server_requ