-- challenge chal_quiz_otl_421 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_otl_421', (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-otl-4-2' AND is_deleted = false LIMIT 1), 'burn-rate-windows', 'Read a burn-rate alert', 'Two statements on the burn-1h rule of the submit SLO (99.5%, rolling 28 days): what the two windows say after an outage, and which error ratio the factor 14.4 really stands for.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_421');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_421');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_421'), 'SLO: 99.5% of valid POST /submissions requests are good, rolling 28 days.
Rule burn-1h (page): burn rate(1 h) > 14.4 AND burn rate(5 min) > 14.4, burn rate = error ratio / (1 - SLO).

Dashboard at 10:40:
window   valid requests   bad     error ratio
1 h      118,400          9,590   8.10%
5 min    9,870            39      0.395%
Deploy log: 10:31 rollback of grader 2026.10.29-1 finished

Statement: "burn-1h is not firing at 10:40, even though the last hour spent the error budget more than 14.4 times too fast."', 'single_choice'::question_type, 'True. The 1-hour burn rate is 8.10% / 0.5% = 16.2, above 14.4, but the 5-minute burn rate is 0.395% / 0.5% = 0.79, far below it, so the AND is false and the page resolves. That is the purpose of the short window: the hour still remembers the outage, the last five minutes show that the rollback at 10:31 fixed it. Without the short window the page would keep firing for up to an hour after recovery, and the on-call engineer could not tell whether the fix worked. The misconception is to read a resolved page as "the budget is fine": the hour did spend about 2% of the 28-day budget, and the SLO report still shows it.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_421') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_421'), 'prometheus/rules/slo-submit-alerts.yml (SLO 99.5%, rolling 28 days):

- alert: SubmitBurnRate1h
  expr: |
    slo:submit_error_ratio:rate1h > (14.4 * 0.005)
    and slo:submit_error_ratio:rate5m > (14.4 * 0.005)
  labels:
    severity: page

Statement: "This rule pages only when more than 14.4% of the submit requests failed, both over the last hour and over the last 5 minutes."', 'single_choice'::question_type, 'False. 14.4 is a burn rate, not a percentage. The threshold is 14.4 x 0.005 = 0.072: the rule pages when more than 7.2% of valid requests failed in both windows. At that error ratio the service spends its budget 14.4 times faster than the rate that would last exactly 28 days, about 2.1% of the 28-day budget per hour (2% for the Workbook''s 30-day window). Reading the factor as a percentage would double the threshold and hide every outage between 7.2% and 14.4%. The misconception is to treat burn rate and error ratio as the same number; they differ by the factor 1 / (1 - SLO).', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_421') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_otl_422 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_otl_422', (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-otl-4-2' AND is_deleted = false LIMIT 1), 'slo-burn-rate-replay', 'SLO burn rate: replay a multi-window policy', 'Before the submit endpoint''s new alerts go live, the CodeDev SRE team wants to replay them on recorded traffic. Write evaluate(slo, minRequests, rules, minutes): it replays per-minute counts of POST /submissions and returns when each burn-rate rule would have started and stopped alerting.

Data. minutes[i] = { good, bad } is minute i of the recording (minute 0 first). The window of length L at minute t holds minutes t - L + 1 .. t. The burn rate of a window is Math.round(((bad / total) / (1 - slo)) * 100) / 100, where bad and total = good + bad are summed over the minutes of the window: the error ratio divided by the error budget, rounded to 2 decimals with Math.round. Write burnRate exactly like this, so cases at the boundary come out the same.

Rule. A rule { name, severity ("page" or "ticket"), factor, longMinutes, shortMinutes } is firing at minute t when all three hold: (1) t >= longMinutes - 1, so the recording covers the whole long window (before that the rule is not firing); (2) the long window and the short window each contain at least minRequests requests; (3) the burn rate of the long window is greater than factor AND the burn rate of the short window is greater than factor (strictly greater, compared after rounding). Rules are independent: several can fire at the same minute.

Result. One alert { rule, severity, start, stop, peak } per firing period of each rule: start = the first firing minute, stop = the first later minute at which the rule is not firing (null if it is still firing at the last minute), peak = the highest long-window burn rate over the firing minutes. Sort the alerts by start; alerts with the same start keep the order of rules.

Invalid input. Throw a RangeError when slo is not a number strictly between 0 and 1, minRequests is not a whole number >= 1, a rule''s factor is not a finite number > 0, shortMinutes is not a whole number >= 1, longMinutes is not a whole number greater than shortMinutes, or a minute has a good or bad count that is not a whole number >= 0.

Tests. Most use the SRE Workbook policy with slo 0.995 and minRequests 100: burn-1h (page, 14.4, 60, 5), burn-6h (page, 6, 360, 30), burn-3d (ticket, 1, 4320, 360); some use a subset. Input on stdin: { slo, minRequests, rules, minutes: [[count, good, bad], ...] }; the runner expands each entry into count identical minutes (up to 20,160 minutes, two weeks), calls evaluate and prints "<n> minutes, alerts: <k>" and one line per alert, for example "page burn-1h: 190 -> 204, peak 26.8x" ("still firing" when stop is null), or "error RangeError".', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_422');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_422'), 1, 'At one minute t, which four numbers decide whether a rule fires, and which checks can make the rule silent before you compare any burn rate with the factor?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_422'), 2, 'Check in this order: is the long window complete (t >= longMinutes - 1), do both windows hold at least minRequests requests, are both rounded burn rates strictly above the factor? For the window sums, a running total (sum[i] = requests in minutes 0 .. i - 1) gives any window as sum[t + 1] - sum[t + 1 - L], so you do not re-add 4,320 minutes for every minute of a 3-day window. The alert only changes at an edge: firing after not firing opens an alert, not firing after firing closes it with stop = t.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_422'), 3, 'A worked example on other numbers: slo 0.99 (budget 1%), minRequests 50, one rule with factor 10, longMinutes 4, shortMinutes 2, and minutes (good, bad): (90, 10) (90, 10) (80, 20) (70, 30) (95, 5) (100, 0). Minutes 0-2: not firing, the 4-minute window is not complete. Minute 3: long 70 bad of 400 = 17.5% -> burn 17.5; short 50 of 200 -> 25: firing, the alert opens at 3. Minute 4: long 65 of 400 -> 16.25, short 35 of 200 -> 17.5: still firing. Minute 5: long 55 of 400 -> 13.75, but short 5 of 200 -> 2.5: not firing, stop = 5. Result: start 3, stop 5, peak 17.5.');
