VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_422'), 'A 20-minute outage at 40% errors pages on burn-1h and stops 5 minutes after it ends', '{"slo":0.995,"minRequests":100,"rules":[{"name":"burn-1h","severity":"page","factor":14.4,"longMinutes":60,"shortMinutes":5},{"name":"burn-6h","severity":"page","factor":6,"longMinutes":360,"shortMinutes":30},{"name":"burn-3d","severity":"ticket","factor":1,"longMinutes":4320,"shortMinutes":360}],"minutes":[[180,1998,2],[20,1200,800],[200,1998,2]]}', '"400 minutes, alerts: 1\npage burn-1h: 190 -> 204, peak 26.8x"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_422'), 'A 2-hour outage at 10% errors: burn-1h pages first, burn-6h joins later', '{"slo":0.995,"minRequests":100,"rules":[{"name":"burn-1h","severity":"page","factor":14.4,"longMinutes":60,"shortMinutes":5},{"name":"burn-6h","severity":"page","factor":6,"longMinutes":360,"shortMinutes":30},{"name":"burn-3d","severity":"ticket","factor":1,"longMinutes":4320,"shortMinutes":360}],"minutes":[[400,1998,2],[120,1800,200],[200,1998,2]]}', '"720 minutes, alerts: 2\npage burn-1h: 443 -> 521, peak 20x\npage burn-6h: 505 -> 541, peak 6.8x"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_422'), 'First hour: the rule waits for a full long window; short spikes never page', '{"slo":0.995,"minRequests":100,"rules":[{"name":"burn-1h","severity":"page","factor":14.4,"longMinutes":60,"shortMinutes":5}],"minutes":[[10,1998,2],[80,1200,800],[100,1998,2],[3,1000,1000],[120,1998,2],[1,0,2000],[60,1998,2]]}', '"374 minutes, alerts: 1\npage burn-1h: 59 -> 94, peak 80x"', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_422'), 'Three days at 1% errors open a burn-3d ticket and no page', '{"slo":0.995,"minRequests":100,"rules":[{"name":"burn-1h","severity":"page","factor":14.4,"longMinutes":60,"shortMinutes":5},{"name":"burn-6h","severity":"page","factor":6,"longMinutes":360,"shortMinutes":30},{"name":"burn-3d","severity":"ticket","factor":1,"longMinutes":4320,"shortMinutes":360}],"minutes":[[1440,999,1],[4320,990,10],[1440,999,1]]}', '"7200 minutes, alerts: 1\nticket burn-3d: 4319 -> 5958, peak 2x"', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_422'), 'Night traffic under 100 requests in 5 minutes: burn-1h stays quiet, burn-6h still pages', '{"slo":0.995,"minRequests":100,"rules":[{"name":"burn-1h","severity":"page","factor":14.4,"longMinutes":60,"shortMinutes":5},{"name":"burn-6h","severity":"page","factor":6,"longMinutes":360,"shortMinutes":30}],"minutes":[[300,1998,2],[360,12,0],[90,12,3],[120,12,0],[100,1998,2]]}', '"970 minutes, alerts: 1\npage burn-6h: 704 -> 776, peak 11.76x"', 3, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_422'), 'Boundary: a burn rate that rounds to exactly 14.4 does not page, 14.6 does', '{"slo":0.995,"minRequests":100,"rules":[{"name":"burn-1h","severity":"page","factor":14.4,"longMinutes":60,"shortMinutes":5}],"minutes":[[60,928,72],[1,927,73],[59,928,72],[60,927,73],[60,998,2]]}', '"240 minutes, alerts: 1\npage burn-1h: 121 -> 180, peak 14.6x"', 3, false, true, 6),
