WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-otl-4-3' AND is_deleted = false);

-- challenge chal_quiz_otl_431 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_otl_431', (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-otl-4-3' AND is_deleted = false LIMIT 1), 'noisy-alert-evidence', 'Why the submit alert was noisy and blind', 'Two statements on last week''s pager log for POST /submissions: whether a higher threshold would have fixed it, and what the slow leak since Wednesday means for the error budget and the alert policy.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_431');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_431');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_431'), 'Alert SubmitErrorRateHigh: page when 5xx / all POST /submissions requests over [1m] > 0.01
Pager log, Mon 2026-10-19 .. Sun 2026-10-25: 14 pages
fired       resolved    value   requests in that minute
Mon 10:12   Mon 10:13   3.1%    424
Tue 03:05   Tue 03:06   3.1%    130
Wed 13:47   Wed 13:48   3.0%    560
... 11 more, every one resolved after 1 minute, on-call note "spike, no action"

Error ratio per day (SLO 99.5%, rolling 28 days): Mon 0.09%  Tue 0.08%  Wed 0.66%  Thu 0.77%  Fri 0.80%  Sat 0.81%  Sun 0.79%
Release 2026.10.21-2 went out Wednesday 09:00. Error budget left: Mon 41%, Sun 10%.

Statement: "Raising the threshold from 1% to 5% fixes both problems of this week."', 'single_choice'::question_type, 'False. A 5% threshold would have silenced the 14 spikes, which were all around 3%, but the real problem of the week was a 0.8% error ratio from Wednesday on, and 0.8% is even further below 5% than below 1%. The rule still looks at one minute and knows nothing about the error budget, so it stays blind to every slow leak and now also to partial failures between 1% and 5%. The misconception is that noise and blindness are two ends of one threshold: any single-window threshold trades one for the other. A burn-rate policy with several windows handles both: a fast pair pages large burns, a slow pair opens a ticket for small ones.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_431') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_431'), 'Alert SubmitErrorRateHigh: page when 5xx / all POST /submissions requests over [1m] > 0.01
Pager log, Mon 2026-10-19 .. Sun 2026-10-25: 14 pages
fired       resolved    value   requests in that minute
Mon 10:12   Mon 10:13   3.1%    424
Tue 03:05   Tue 03:06   3.1%    130
Wed 13:47   Wed 13:48   3.0%    560
... 11 more, every one resolved after 1 minute, on-call note "spike, no action"

Error ratio per day (SLO 99.5%, rolling 28 days): Mon 0.09%  Tue 0.08%  Wed 0.66%  Thu 0.77%  Fri 0.80%  Sat 0.81%  Sun 0.79%
Release 2026.10.21-2 went out Wednesday 09:00. Error budget left: Mon 41%, Sun 10%.

New policy (burn rate = error ratio / (1 - SLO), both windows must exceed the factor):
burn-1h  page    14.4   1 h / 5 min
burn-6h  page    6      6 h / 30 min
burn-3d  ticket  1      3 days / 6 h

Statement: "At 0.8% the release burns the budget 1.6 times too fast: a full 28-day budget would last 17.5 days, so burn-3d can catch this leak, while burn-1h and burn-6h never fire on it as long as the ratio stays at 0.8%."', 'single_choice'::question_type, 'True. Burn rate = 0.8% / 0.5% = 1.6, and a budget meant for 28 days lasts 28 / 1.6 = 17.5 days at that rate. 1.6 is above the factor 1 of burn-3d, so once the leak covers enough of the 3-day window (and the last 6 hours still show it) a ticket opens; it is far below 6 and 14.4, so neither page rule fires. That is the intended severity: there are days, not minutes, to fix it, but it must not be ignored. The misconception is that a slow leak is harmless because no single minute looks bad; this one spent 30% of the budget in five days.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_otl_431') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_otl_432 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_otl_432', (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-otl-4-3' AND is_deleted = false LIMIT 1), 'fix-noisy-submit-alert', 'Fix the noisy submit alert', 'Symptom. The on-call alert for POST /submissions pages when more than 1% of the requests in a single minute fail. Last week it paged 14 times, every time for a one-minute spike that was over before anyone opened a laptop, and it stayed silent while a release on Wednesday at 09:00 made 0.8% of submissions fail for the rest of the week and spent 30% of the 28-day error budget. The replay tool below evaluates the shipped rule on recorded traffic. Fix it so it evaluates this multi-window burn-rate policy instead (SLO: 99.5% of valid submit requests are good over 28 days):

burn-1h: page, factor 14.4, long window 60 minutes, short window 5 minutes
burn-6h: page, factor 6, long window 360 minutes, short window 30 minutes
burn-3d: ticket, factor 1, long window 4320 minutes, short window 360 minutes

The window of length L at minute t holds minutes t - L + 1 .. t. Burn rate of a window = burnRate(bad, total) as already written in the file: Math.round(((bad / total) / (1 - 0.995)) * 100) / 100. A rule is firing at minute t when all three hold: t >= long - 1 (the recording covers the whole long window); the long window and the short window each hold at least 100 requests; the burn rate of the long window is greater than the factor AND the burn rate of the short window is greater than the factor. Each rule is checked on its own, several can fire at the same minute, and the firing rules are listed in the order above. notifications() already turns each firing period of a rule into one notification with its start and its stop (the first minute it is no longer firing); keep it and the test runner as they are.

Input (stdin): { minutes: [[count, good, bad], ...] }; the runner expands each entry into count identical minutes (minute 0 is day 1 00:00), replays them and prints one line per notification, for example "PAGE burn-1h: day 1 10:14 -> day 1 10:28" ("still firing" when it never stopped), then "<n> minutes replayed: <p> pages, <t> tickets". The tests replay recorded days and weeks: the incident week, outages, short bursts, low traffic at night, recordings shorter than an hour and two noisy weeks.', 'open', 'hard'::difficulty_question, 'fix_bug', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_432');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_432'), 1, 'The shipped rule asks "did this minute look bad?". Which question should a page answer instead, and how many windows does it take to answer it without paging on spikes or staying silent on a slow leak?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_432'), 2, 'Only firingRules decides; windowTotals already sums any window, burnRate already turns it into a rounded burn rate, and notifications() handles start and stop. For each rule of the policy, check in this order: is the long window complete, do both windows hold at least 100 requests, are both burn rates strictly above the factor?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_432'), 3, 'A similar check on other numbers, for a rule with factor 6, long window 360 and short window 30 at minute 400, with 1,500 requests a minute: the long window holds 540,000 requests of which 18,000 failed (3.33%, burn rate 6.67), the short window 45,000 requests of which 450 failed (1%, burn rate 2). The long window alone would say page, but the short one says the problem has stopped: not firing. With 4,500 failures in the short window (10%, burn rate 20) it would fire. The same rule on a recording of only 200 minutes never fires, because its 360-minute window is not complete.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_432'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_432');
