INSERT INTO storage.assets (public_id, provider, object_key, resource_type, mine_type, file_size, original_name)
VALUES ('ast_chal_coding_otl_432_starter', 's3', 'challenges/typescript/chal_coding_otl_432/starter.ts', 'raw', 'application/typescript', 3484, 'main.ts')
ON CONFLICT (public_id) DO UPDATE SET object_key = EXCLUDED.object_key, file_size = EXCLUDED.file_size, mine_type = EXCLUDED.mine_type, original_name = EXCLUDED.original_name, updated_at = now();
INSERT INTO challenge.coding_files (challenge_id, language, file_path, file_role, asset_id)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_otl_432'), 'typescript', 'main.ts', 'starter', (SELECT id FROM storage.assets WHERE public_id = 'ast_chal_coding_otl_432_starter'))
ON CONFLICT ON CONSTRAINT uq_coding_files_path DO UPDATE SET file_role = EXCLUDED.file_role, asset_id = EXCLUDED.asset_id, updated_at = now();

-- learners enrolled before these lessons existed
INSERT INTO learning.history (user_id, course_id, module_id, lesson_id)
SELECT r.user_id, r.course_id, m.id, l.id
FROM learning.register r
JOIN course.module m ON m.course_id = r.course_id AND m.is_deleted = false
JOIN course.lesson l ON l.module_id = m.id AND l.is_deleted = false
WHERE r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry') AND r.is_deleted = false
ON CONFLICT DO NOTHING;
WITH ordered AS (
    SELECT h.user_id, h.lesson_id, h.status,
           row_number() OVER (PARTITION BY h.user_id ORDER BY m.order_index, l.order_index) AS rn
    FROM learning.history h
    JOIN course.lesson l ON l.id = h.lesson_id AND l.is_deleted = false
    JOIN course.module m ON m.id = l.module_id AND m.is_deleted = false
    WHERE h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry')
),
next_lesson AS (
    SELECT DISTINCT ON (o.user_id) o.user_id, o.lesson_id
    FROM ordered o
    WHERE o.status = 'enrolled'
      AND NOT EXISTS (SELECT 1 FROM ordered p WHERE p.user_id = o.user_id AND p.rn < o.rn AND p.status <> 'completed')
    ORDER BY o.user_id, o.rn
)
UPDATE learning.history h
SET status = 'in_progress', updated_at = now()
FROM next_lesson n
JOIN learning.register r ON r.user_id = n.user_id AND r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry') AND r.is_deleted = false AND r.status <> 'enrolled'
WHERE h.user_id = n.user_id AND h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry') AND h.lesson_id = n.lesson_id;
UPDATE learning.register r
SET status = 'in_progress'
WHERE r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry') AND r.status = 'completed'
  AND EXISTS (SELECT 1 FROM learning.history h WHERE h.user_id = r.user_id AND h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'observability-opentelemetry') AND h.status <> 'completed');

COMMIT;
